using System;
using System.Text.Json;
using System.Text.Json.Serialization;

// PROGRAM: Eksperimen Serialisasi Modern System.Text.Json
public record PaymentPayload(
    [property: JsonPropertyName("transaction_id")] string TxId,
    [property: JsonPropertyName("amount")] decimal Amount,
    [property: JsonConverter(typeof(JsonStringEnumConverter))] PaymentStatus Status
);

public enum PaymentStatus { Pending, Settled, Failed }

public class Program
{
    public static void Main()
    {
        var payload = new PaymentPayload("TX-007", 750_000m, PaymentStatus.Settled);

        // Serialisasi ke format JSON
        var options = new JsonSerializerOptions
        {
            WriteIndented = true,
            DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull
        };

        string jsonString = JsonSerializer.Serialize(payload, options);
        Console.WriteLine("=== HASIL SERIALISASI JSON ===");
        Console.WriteLine(jsonString);

        // Deserialisasi kembali ke Objek C#
        var deserialized = JsonSerializer.Deserialize<PaymentPayload>(jsonString, options);
        Console.WriteLine($"\nDeserialized Sukses -> Status: {deserialized?.Status}, Nominal: Rp {deserialized?.Amount:N0}");
    }
}

